// Items bruts d'un noeud + indicateur « le noeud a bien tourne »
const brut = (nom) => {
  try {
    return [$(nom).all().map((i) => i.json), true]
  } catch (e) {
    return [[], false]
  }
}
// alwaysOutputData produit un item vide {} quand il n'y a aucun resultat :
// on l'ecarte, comme les items d'erreur de « continue on error ».
const nettoie = (liste) => liste.filter((j) => j && !j.error && Object.keys(j).length > 0)

// Indisponible = noeud jamais lance, ou n'ayant produit que des erreurs.
const dispo = (lance, bruts) => {
  if (!lance) return false
  if (bruts.some((j) => j && j.error) && nettoie(bruts).length === 0) return false
  return true
}

const [agendaBrut, agendaLance] = brut('Agenda du jour')
const [cockpitBrut, cockpitLance] = brut('État cockpit')
const [callsBrut, callsLance] = brut('Calls récents')
const [emailsBrut, emailsLance] = brut('Emails récents')

const zone = 'Europe/Paris'
const aujourdHui = $now.setZone(zone).toISODate()
const dateDemain = $now.setZone(zone).plus({ days: 1 }).toISODate()
const jourDe = (iso) => {
  if (!iso) return null
  try {
    return DateTime.fromISO(iso).setZone(zone).toISODate()
  } catch (e) {
    return null
  }
}

const evenements = nettoie(agendaBrut).map((e) => ({
  titre: e.summary ?? '(sans titre)',
  debut: e.start?.dateTime ?? e.start?.date ?? null,
  fin: e.end?.dateTime ?? e.end?.date ?? null,
  invites: Array.isArray(e.attendees) ? e.attendees.length : 0,
}))

// Garde-fou : quoi que l'API ait renvoye, seuls aujourd'hui et demain passent.
const agenda = evenements.filter((e) => jourDe(e.debut) === aujourdHui)
const demain = evenements.filter((e) => jourDe(e.debut) === dateDemain)

const cockpit = nettoie(cockpitBrut)

const calls = nettoie(callsBrut).map((c) => ({
  titre: c.titre,
  date: c.date,
  extrait: String(c.extrait ?? '').slice(0, 2000),
}))

const emails = nettoie(emailsBrut).map((m) => ({
  de: m.from ?? m.From ?? '',
  sujet: m.subject ?? m.Subject ?? '(sans objet)',
  extrait: String(m.snippet ?? '').slice(0, 140),
}))

return [{
  json: {
    date: $now.setZone(zone).setLocale('fr').toFormat("cccc d LLLL yyyy"),
    sources_indisponibles: [
      dispo(agendaLance, agendaBrut) ? null : 'agenda',
      dispo(cockpitLance, cockpitBrut) ? null : 'cockpit',
      dispo(emailsLance, emailsBrut) ? null : 'emails',
      dispo(callsLance, callsBrut) ? null : 'calls',
    ].filter(Boolean),
    agenda,
    demain,
    cockpit,
    emails,
    calls,
  },
}]
